      "grounding":[{"end_line":1830,"quote":"Reducing coupling\nmeans reducing the number of places where meaning can be invented.","section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/DESIGN_MODULE.md#DESIGN_MODULE%2F10.%20Realisation%20rules%2FCoupling","start_line":1829}],
