      "grounding":[{"end_line":191,"quote":"The assessor records its\nexpectations from the governing source before opening the candidate; it\nreads the subject at that identity or relation, never a mutable working\ntree; it makes no repair; it does not assess its\nown authorship.","section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EVALUATION.md#EVALUATION%2F3.%20Independent%20assessment","start_line":186}],
